import re

_DETAIL = re.compile(r"^/items/([1-9][0-9]*)/?$")


def resolve_inventory_request(method, path):
    if not isinstance(method, str) or not isinstance(path, str):
        raise TypeError("method and path must be strings")
    if method == "GET" and path == "/items/":
        return ("list_items", {})
    if method == "POST" and path == "/items/add/":
        return ("create_item", {})
    match = _DETAIL.fullmatch(path)
    if match is None:
        return None
    item_id = int(match.group(1))
    actions = {
        "GET": "get_item",
        "PUT": "update_item",
        "DELETE": "delete_item",
    }
    action = actions.get(method)
    if action is None:
        return None
    return (action, {"id": item_id})

